def feasible(job, out):
    leases = {l['id']: l for l in job['leases']}
    requests = {r['id']: r for r in job['requests']}
    offers = {o['id']: o for o in job['offers']}
    rnodes = {n['id']: n for n in job['request_quotas']}
    onodes = {n['id']: n for n in job['offer_quotas']}
    active = {row['id']: row['active'] for row in out['active_requests']}
    import ipaddress
    rows = out['plan']['assignments']
    ids = [r['request'] for r in rows]
    if ids != sorted(ids):
        return 'not sorted'
    if len(set(ids)) != len(ids):
        return 'duplicate request'
    used = {}
    rq_use = {}
    oq_use = {}
    total = 0
    for row in rows:
        rid, oid = row['request'], row['offer']
        if not active.get(rid):
            return 'inactive request'
        r, o = requests[rid], offers[oid]
        if r['service'] != o['service']:
            return 'service mismatch'
        if not (r['at'] <= o['time'] < leases[r['lease']]['end']):
            return 'time window'
        if ipaddress.IPv6Address(r['target']) not in ipaddress.IPv6Network(o['prefix']):
            return 'prefix'
        if oid not in o['requests']:
            return 'not listed'
        used[oid] = used.get(oid, 0) + 1
        total += o['cost']
        g = r['group']
        while g is not None and g in rnodes:
            rq_use[g] = rq_use.get(g, 0) + 1
            g = rnodes[g]['parent']
        g = o['group']
        while g is not None and g in onodes:
            oq_use[g] = oq_use.get(g, 0) + 1
            g = onodes[g]['parent']
    for oid, count in used.items():
        if count > offers[oid]['capacity']:
            return 'offer capacity'
    for g, count in rq_use.items():
        if count > rnodes[g]['capacity']:
            return 'request quota %s' % g
    for g, count in oq_use.items():
        if count > onodes[g]['capacity']:
            return 'offer quota %s' % g
    if total != out['plan']['cost']:
        return 'cost mismatch %d != %d' % (total, out['plan']['cost'])
    if len(rows) != out['plan']['resolved']:
        return 'resolved mismatch'
    return None

